# >>> STATIC
_static_general_reload_flags() {
    cat <<-'ARGCEOF'
	conf	Reload the NetworkManager.conf configuration from disk
	dns-rc	Update DNS configuration, which usually involves writing /etc/resolv.conf anew
	dns-full	Restart the DNS plugin
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
_choice_nmcli_bssid() {
    nmcli -t -e no -f BSSID device wifi list 2>/dev/null
}

_choice_nmcli_connection() {
    nmcli -t -e no -f NAME connection show 2>/dev/null
}

_choice_nmcli_device() {
    nmcli -t -e no -f DEVICE device status 2>/dev/null
}

_choice_nmcli_device_property() {
    printf '%s\n' autoconnect managed
}

_choice_nmcli_log_domain() {
    printf '%s\n' ALL NONE DEFAULT DHCP IP PLATFORM RFKILL ETHER WIFI BT MB DHCP4 DHCP6 PPP WIFI_SCAN IP4 IP6 AUTOIP4 DNS VPN SHARING SUPPLICANT AGENTS SETTINGS SUSPEND CORE DEVICE OLPC WIMAX INFINIBAND FIREWALL ADSL BOND VLAN BRIDGE DBUS_PROPS TEAM CONCHECK DCB DISPATCH AUDIT SYSTEMD VPN_PLUGIN PROXY
}

_choice_nmcli_log_level() {
    printf '%s\n' OFF ERR WARN INFO DEBUG TRACE
}

_choice_nmcli_setting_property() {
    [[ -n "${argc_id:-}" ]] || return 0
    nmcli -t -e no connection show "$argc_id" 2>/dev/null | sed 's/:.*//'
}

_choice_nmcli_ssid() {
    nmcli -t -e no -f SSID device wifi list 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
